// SHA3_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module SHA3_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [2:0] c_mode,
  input logic  c_start,
  input logic [63:0] c_in_data,
  input logic [3:0] c_in_bytes,
  input logic  c_in_last,
  input logic [63:0] c_out_data,
  input logic  c_out_last,
  input logic  c_busy,
  input logic  c_in_valid,
  input logic  c_in_ready,
  input logic  c_out_valid,
  input logic  c_out_ready,
  input logic  c_done,
  input logic  c_err
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 14;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:13];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_MSG;          // full / valid pulse / available
  logic m_state_DIGEST;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_err) m_set[1] = 1'b1;
    if (m_state_MSG && c_in_ready) m_set[2] = 1'b1;
    if (m_wr && m_map && (m_idx == 7 || m_idx == 8 || m_idx == 9) && m_state_MSG) m_set[3] = 1'b1;
    if (c_out_valid && !m_state_DIGEST) m_set[4] = 1'b1;
    if (c_out_valid && m_state_DIGEST && (m_rd && m_map && m_idx == 12)) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h1;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_MSG <= 0;
      m_state_DIGEST <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 6) ? PWDATA & m_be & 32'h1 : 0;
      if (m_wr && m_map && m_idx == 7 && !m_state_MSG) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8 && !m_state_MSG) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9 && !m_state_MSG) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 9 && !m_state_MSG) m_state_MSG <= 1;
      if (m_state_MSG && c_in_ready) m_state_MSG <= 0;
      if (c_out_valid && (!m_state_DIGEST || (m_rd && m_map && m_idx == 12))) begin
        m_w[10] <= (32'(c_out_data[31:0]) << 0);
        m_w[11] <= (32'(c_out_data[63:32]) << 0);
        m_w[12] <= (32'(c_out_last) << 0);
        m_state_DIGEST <= 1;
      end else if ((m_rd && m_map && m_idx == 12)) m_state_DIGEST <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h53330100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_DIGEST, m_state_MSG});
      4: return m_w[4];
      5: return m_w[5];
      6: return 0;
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return (32'(c_busy) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_mode, c_mode == m_w[5][2:0])
  `SVA_INV(a_core_start, c_start == m_pulse_CMD[0])
  `SVA_INV(a_core_in_data_31_0, c_in_data[31:0] == m_w[7][31:0])
  `SVA_INV(a_core_in_data_63_32, c_in_data[63:32] == m_w[8][31:0])
  `SVA_INV(a_core_in_bytes, c_in_bytes == m_w[9][3:0])
  `SVA_INV(a_core_in_last, c_in_last == m_w[9][4:4])
  `SVA_INV(a_core_in_valid, c_in_valid == m_state_MSG)
  `SVA_INV(a_core_out_ready, c_out_ready == (!m_state_DIGEST || (m_rd && m_map && m_idx == 12)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_mode == 3'h1 && c_start == 1'h0 && c_in_data[31:0] == 32'h0 && c_in_data[63:32] == 32'h0 && c_in_bytes == 4'h0 && c_in_last == 1'h0 && !c_in_valid && c_out_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_CMD, m_rd && m_map && m_idx == 6)
  `FC(wr_CMD, m_wr && m_map && m_idx == 6)
  `FC(rd_MSG0, m_rd && m_map && m_idx == 7)
  `FC(wr_MSG0, m_wr && m_map && m_idx == 7)
  `FC(rd_MSG1, m_rd && m_map && m_idx == 8)
  `FC(wr_MSG1, m_wr && m_map && m_idx == 8)
  `FC(rd_MSG2, m_rd && m_map && m_idx == 9)
  `FC(wr_MSG2, m_wr && m_map && m_idx == 9)
  `FC(rd_DIGEST0, m_rd && m_map && m_idx == 10)
  `FC(wr_DIGEST0, m_wr && m_map && m_idx == 10)
  `FC(rd_DIGEST1, m_rd && m_map && m_idx == 11)
  `FC(wr_DIGEST1, m_wr && m_map && m_idx == 11)
  `FC(rd_DIGEST2, m_rd && m_map && m_idx == 12)
  `FC(wr_DIGEST2, m_wr && m_map && m_idx == 12)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 13)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 13)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE_set, m_set[0])
  `FC(irq_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ERR_set, m_set[1])
  `FC(irq_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_MSG_DONE_set, m_set[2])
  `FC(irq_MSG_DONE_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_MSG_DONE_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_MSG_DONE_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_MSG_OVF_set, m_set[3])
  `FC(irq_MSG_OVF_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_MSG_OVF_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_MSG_OVF_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_DIGEST_AVAIL_set, m_set[4])
  `FC(irq_DIGEST_AVAIL_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_DIGEST_AVAIL_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_DIGEST_AVAIL_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(cmd_start, m_pulse_CMD[0])
  `FC(MSG_handshake, m_state_MSG && c_in_ready)
  `FC(MSG_backpressure, m_state_MSG && !c_in_ready)
  `FC(MSG_write_while_full, m_wr && m_map && m_idx == 9 && m_state_MSG)
  `FC(DIGEST_capture, c_out_valid && !m_state_DIGEST)
  `FC(DIGEST_backpressure, c_out_valid && m_state_DIGEST && !(m_rd && m_map && m_idx == 12))
  `FC(DIGEST_pop, m_rd && m_map && m_idx == 12 && m_state_DIGEST)
  `FC(DIGEST_read_empty, m_rd && m_map && m_idx == 12 && !m_state_DIGEST)
  `FC(DIGEST_pop_and_capture, c_out_valid && m_state_DIGEST && m_rd && m_map && m_idx == 12)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind SHA3_apb SHA3_apb_sva u_apb_sva (.*);
